INSERT INTO feature VALUES('termination-certificates','rules','Replayable termination certificates',NULL,'partial','notable',NULL,'One termination evidence form shared by rule blocks and fixpoints: a path order''s derivation over the precedence as data, each step naming the clause that orients it, which the kernel replays for an operation''s rules and a theory''s rules, the front end reads for a description''s faces and the cell layer reads to break its completion''s size ties; a size measure for a fixpoint is still to come.','theory-path-orders kernel-term theory-levitation theory-cell-complexes','crates/theory-path-orders/tests/lpo.rs corpus/model/data/rule-equation.gandr corpus/pathological/data/rule-equation-unoriented.gandr','corpus/ledger/features/termination-certificates.gandr','#314 #392');
